import { test, expect } from '@playwright/test';

test.describe('Loading Skeleton Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
  });

  test('should display loading skeleton while fetching data', async ({ page }) => {
    await page.click(getByRole('button', { name: /fetch data/i }));
    const skeleton = page.getByText(/loading.../i);
    await expect(skeleton).toBeVisible();
  });

  test('should hide loading skeleton after data is fetched', async ({ page }) => {
    await page.click(getByRole('button', { name: /fetch data/i }));
    const skeleton = page.getByText(/loading.../i);
    await expect(skeleton).toBeVisible();

    // Simulate API response delay
    await page.waitForTimeout(2000);

    const dataElement = page.getByText(/data loaded/i);
    await expect(skeleton).toBeHidden();
    await expect(dataElement).toBeVisible();
  });
});
